"""A small in-memory key-value store with expiration and LRU eviction."""

from collections import OrderedDict
from time import monotonic


class TinyKV:
    """Store values in memory.

    ``max_items`` limits live entries; ``None`` means no limit. ``clock`` is
    a callable returning time in seconds, and defaults to a monotonic clock.
    Accessing or setting an entry makes it the most recently used entry.
    """

    def __init__(self, max_items=None, clock=None):
        if max_items is not None and (
            isinstance(max_items, bool) or not isinstance(max_items, int) or max_items < 0
        ):
            raise ValueError("max_items must be a non-negative integer or None")
        self.max_items = max_items
        self.clock = monotonic if clock is None else clock
        self._items = OrderedDict()

    def _purge_expired(self, now):
        for key, (_, expires_at) in list(self._items.items()):
            if expires_at is not None and now >= expires_at:
                del self._items[key]

    def set(self, key, value, ttl=None):
        """Set a value, optionally expiring it after ``ttl`` seconds."""
        now = self.clock()
        self._purge_expired(now)
        # Remove an old value even if its replacement expires immediately.
        self._items.pop(key, None)
        if ttl is not None and ttl <= 0:
            return
        expires_at = None if ttl is None else now + ttl
        self._items[key] = (value, expires_at)
        if self.max_items is not None:
            while len(self._items) > self.max_items:
                self._items.popitem(last=False)

    def get(self, key, default=None):
        """Return a live value, or ``default`` if it is missing or expired."""
        try:
            value, expires_at = self._items[key]
        except KeyError:
            return default
        if expires_at is not None and self.clock() >= expires_at:
            del self._items[key]
            return default
        self._items.move_to_end(key)
        return value

    def delete(self, key):
        """Remove a key; return whether it existed and was not expired."""
        try:
            _, expires_at = self._items.pop(key)
        except KeyError:
            return False
        return expires_at is None or self.clock() < expires_at

